import{_ as o,o as a,c as i,a2 as r}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"공식 플러그인 예제 분석","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/dev-guide/examples.md","filePath":"ko-KR/dev-guide/examples.md","lastUpdated":1788085660000}'),d={name:"ko-KR/dev-guide/examples.md"};function l(c,e,t,n,s,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="공식-플러그인-예제-분석" tabindex="-1">공식 플러그인 예제 분석 <a class="header-anchor" href="#공식-플러그인-예제-분석" aria-label="Permalink to &quot;공식 플러그인 예제 분석&quot;">​</a></h1><p><code>Lertaro.PluginSdk</code>의 여러 인터페이스가 실전에서 어떻게 협력하는지 이해하기 위해 공식 리포지토리에 포함된 4가지 대표 오픈소스 플러그인의 구현 패턴을 분석합니다.</p><h2 id="_1-coreextensions-——-액션-shell-메뉴-및-퀵-패널" tabindex="-1">1. CoreExtensions —— 액션, Shell 메뉴 및 퀵 패널 <a class="header-anchor" href="#_1-coreextensions-——-액션-shell-메뉴-및-퀵-패널" aria-label="Permalink to &quot;1. CoreExtensions —— 액션, Shell 메뉴 및 퀵 패널&quot;">​</a></h2><p><code>CoreExtensions</code> 플러그인은 Lertaro의 핵심 기능 확장 패키지로 <code>IPlugin</code>, <code>IActionProvider</code>, <code>IConfigurable</code> 및 여러 하위 프로바이더를 구현합니다.</p><h3 id="핵심-구현-사항" tabindex="-1">핵심 구현 사항 <a class="header-anchor" href="#핵심-구현-사항" aria-label="Permalink to &quot;핵심 구현 사항&quot;">​</a></h3><ul><li><strong>정적 결과 액션 (<code>IActionProvider.GetActions()</code>)</strong>: 열기 및 탐색기에서 위치 찾기, 경로와 파일 복사, 즐겨찾기 추가, 명령 프롬프트, 삭제, 관리자 권한 실행 등 기본 파일 액션 제공.</li><li><strong>네이티브 Shell 메뉴 통합 (<code>IDynamicActionProvider</code>)</strong>: <code>ShellMenuActionProvider</code>를 통해 Windows Shell COM 인터페이스와 연동하여 &quot;보내기&quot;, 7-Zip, VS Code 등 계단식 우클릭 메뉴를 <code>Ctrl+O</code> 액션 메뉴 내에 렌더링.</li><li><strong>스키마 기반 설정 폼 (<code>IConfigurable</code>)</strong>: 그룹화(<code>Group</code>), 문자열 목록(<code>StringList</code>), 단축키 녹화(<code>Hotkey</code>)를 포함한 폼 스키마를 정의하여 XAML 작성 없이 설정 센터에 네이티브 UI 자동 생성.</li><li><strong>다양한 퀵 패널 탭 (<code>IQuickPanelTabProvider</code>)</strong>: <ul><li><code>FavoritesTabProvider</code> / <code>HistoryTabProvider</code>: 메모리 상의 목록을 그대로 결과로 반환하는 제로 I/O 최소 구성.</li><li><code>WindowsRecentTabProvider</code>: 백그라운드에서 <code>Recent</code> 폴더를 탐색하고 COM으로 바로가기 대상을 해석하여 <code>Metadata.Modified</code>를 채워 정렬 지원.</li><li><code>LastDirectoryTabProvider</code> / <code>RecentFilesTabProvider</code>: 호스트가 제공하는 <a href="./sdk/services.html"><code>ExplorerPathService</code></a> 및 <code>RecentFilesService</code>를 직접 조회.</li></ul></li></ul><h2 id="_2-pinyinalias-——-비-ascii-별칭-변환-엔진" tabindex="-1">2. PinyinAlias —— 비 ASCII 별칭 변환 엔진 <a class="header-anchor" href="#_2-pinyinalias-——-비-ascii-별칭-변환-엔진" aria-label="Permalink to &quot;2. PinyinAlias —— 비 ASCII 별칭 변환 엔진&quot;">​</a></h2><p><code>PinyinAlias</code> 플러그인은 중국어 파일명에 대한 병음 전체 및 초성 검색을 지원하며 <code>IAliasProvider</code>와 <code>ITranslationProvider</code>를 구현합니다.</p><h3 id="핵심-구현-사항-1" tabindex="-1">핵심 구현 사항 <a class="header-anchor" href="#핵심-구현-사항-1" aria-label="Permalink to &quot;핵심 구현 사항&quot;">​</a></h3><ul><li><strong>입출력 문자 집합 경계 (<code>InputRanges</code> / <code>OutputRanges</code>)</strong>: 입력 범위를 CJK 한자 블록, 출력 범위를 소문자 <code>a</code>–<code>z</code>로 선언. 호스트는 이 경계를 활용해 한자와 영문이 섞인 쿼리를 자면 매칭과 병음 매칭으로 자동 분할.</li><li><strong>빠른 사전 검사 (<code>CanHandle(text)</code>)</strong>: 별칭 생성 전 한자가 포함되어 있는지 먼저 스캔하여 순수 영문 문자열은 즉시 <code>false</code>를 반환하고 후속 처리를 건너뜀.</li><li><strong>다음자 조합 및 별칭 구성 (<code>GetAliases(text)</code>)</strong>: 음절 맵을 구성하고 여러 발음이 있는 경우 파이프 기호 <code>|</code>로 연결된 후보군을 최대 32개까지 생성하여 병렬 일치 수행.</li><li><strong>임베디드 다국어 및 스레드 안전 캐싱</strong>: <code>ITranslationProvider</code>를 통해 표시 이름을 다국어화하고, 내부에서는 <code>lock</code> 기반 딕셔너리로 JSON 번역을 캐싱하여 반복 파싱 방지.</li></ul><h2 id="_3-flowlauncherbridge-——-커뮤니티-플러그인-호환-및-격리-런타임" tabindex="-1">3. FlowLauncherBridge —— 커뮤니티 플러그인 호환 및 격리 런타임 <a class="header-anchor" href="#_3-flowlauncherbridge-——-커뮤니티-플러그인-호환-및-격리-런타임" aria-label="Permalink to &quot;3. FlowLauncherBridge —— 커뮤니티 플러그인 호환 및 격리 런타임&quot;">​</a></h2><p><code>FlowLauncherBridge</code> 플러그인은 외부 Flow Launcher 생태계를 네이티브급으로 수용하기 위한 대규모 브리지 시스템입니다.</p><h3 id="핵심-구현-사항-2" tabindex="-1">핵심 구현 사항 <a class="header-anchor" href="#핵심-구현-사항-2" aria-label="Permalink to &quot;핵심 구현 사항&quot;">​</a></h3><ul><li><strong>다중 언어 프로세스 간 브리지</strong>: C# (.NET), Python 3.12, Node.js v20 LTS 및 <code>.exe</code> 플러그인을 원활히 실행.</li><li><strong>완전 격리 독립 런타임</strong>: 사용자 데이터 디렉토리 내에 Python / Node.js 런타임을 자동 배치하고 명명된 파이프를 통해 JSON-RPC 통신 수행.</li><li><strong>동적 설정 폼 및 WebView2 리치 미리보기</strong>: 외부 플러그인의 <code>SettingsTemplate.yaml</code>/<code>.json</code>을 <code>PluginConfigSchema</code>로 동적 매핑하고 사전이나 날씨 등의 HTML 카드를 QuickLook 내에 렌더링.</li></ul><h2 id="_4-fileunlocker-——-파일-점유-해제-액션" tabindex="-1">4. FileUnlocker —— 파일 점유 해제 액션 <a class="header-anchor" href="#_4-fileunlocker-——-파일-점유-해제-액션" aria-label="Permalink to &quot;4. FileUnlocker —— 파일 점유 해제 액션&quot;">​</a></h2><p><code>FileUnlocker</code>는 Windows Restart Manager API로 파일 점유를 조회하고 해제를 요청하는 단일 액션 플러그인의 예입니다.</p><h3 id="핵심-구현-사항-3" tabindex="-1">핵심 구현 사항 <a class="header-anchor" href="#핵심-구현-사항-3" aria-label="Permalink to &quot;핵심 구현 사항&quot;">​</a></h3><ul><li><strong>단일 선택 제한</strong>: 존재하는 파일 하나를 선택했을 때만 액션을 제공하여 폴더나 다중 선택에 대한 모호한 요청을 방지.</li><li><strong>프로세스 정보 표시</strong>: 점유 프로세스 이름, PID, 실행 파일 경로를 표시하고 파일 상태 변화에 대응할 새로 고침을 제공.</li><li><strong>요청 기반 해제</strong>: 점유 프로세스에 파일 해제를 요청하며, 프로세스가 없거나 작업 중일 때 해제 버튼을 비활성화.</li><li><strong>호스트 창 프레임</strong>: WPF 뷰를 SDK의 테마 지원 <code>PluginWindow</code> 대화상자에 넣어 플러그인이 테마, DPI, 작업 표시줄, Alt+Tab 처리를 중복 구현하지 않도록 구성.</li></ul>',18)])])}const P=o(d,[["render",l]]);export{g as __pageData,P as default};
